package com.yuegang.zhihui.system.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.security.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.system.application.*;import com.yuegang.zhihui.system.security.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/system/settings")public final class SystemSettingController{private final SystemSettingService service;private final SystemTrustedUserContextResolver users;public SystemSettingController(SystemSettingService s,SystemTrustedUserContextResolver u){service=s;users=u;}@GetMapping ApiResponse<List<SystemSettingView>>list(HttpServletRequest r){admin(r);return ApiResponse.success(service.list(),TraceIdResolver.resolve(r));}@PutMapping("/{key}")ApiResponse<SystemSettingView>update(@PathVariable String key,@Valid @RequestBody UpdateSystemSettingRequest body,HttpServletRequest r){var p=admin(r);return ApiResponse.success(service.update(key,body,Long.parseLong(p.userId())),TraceIdResolver.resolve(r));}private CurrentUserPrincipal admin(HttpServletRequest r){var p=users.resolve(r);if(!p.roles().contains("ADMIN"))throw new BusinessException(ErrorCode.PERMISSION_DENIED);return p;}}
